/* v0.5.1: original course slides, persistent Fine conversations, shared scene plane. */
const COURSE_INTRO=[
 {title:'文字與閱讀',subtitle:'語言、翻譯與文本脈絡',body:['語言文本與文化學系','賴老師　／　課堂講義'],cover:true},
 {title:'閱讀中的推論',body:['文本寫了什麼，讀者又補上了什麼？','「他沒有回答。」可以描述沉默，卻未必足以判定拒絕。','練習時先指出文字依據，再說明這段資料能支持的範圍。']},
 {title:'文字形式與閱讀脈絡',body:['轉述保留原句的語氣。理解一段文字時，也要留意它出現的情境。','比較譯文時，可以觀察分句、指稱與措辭；討論文化詞彙時，還需要考慮讀者的背景。','引文刪節會改變讀者能接觸到的資料。本節以五個例子練習從文字提出判斷。']}
];
function courseSlides(){return COURSE_INTRO.concat(problems.map(p=>({title:p.title,body:p.bullets})))}
function originalPPT(){const slides=courseSlides(),i=Math.max(0,Math.min(7,state.deckPage||0)),s=slides[i];return `<section class="course-ppt"><nav class="ppt-ribbon" aria-label="簡報工具"><b>P</b><span>常用　插入　設計　動畫　投影片放映</span></nav><div class="course-layout"><aside class="course-thumbs">${slides.map((s,j)=>btn('deck:'+j,`<small>${j+1}</small><span>${esc(s.title)}</span>`,'course-thumb '+(i===j?'active':''))).join('')}</aside><div class="course-main"><article class="course-slide ${s.cover?'course-cover':''}"><h1>${esc(s.title)}</h1>${s.subtitle?'<h2>'+esc(s.subtitle)+'</h2>':''}<div class="course-body">${s.body.map(t=>'<p>'+esc(t)+'</p>').join('')}</div><footer><span>文字與閱讀　／　賴老師</span><span>${i+1}</span></footer></article><nav class="course-paging">${btn('deck:'+Math.max(0,i-1),'上一頁','secondary',i===0)}<span>${i+1} / 8</span>${btn('deck:'+Math.min(7,i+1),'下一頁','secondary',i===7)}</nav><div class="course-work">${btn('startreview',state.submitted?'查看校對副本':'開始校對五頁教材','primary',!state.teacherRead)}</div></div></div><div class="appstatus">投影片 ${i+1} / 8<span>文字與閱讀.ppt　原始教材</span></div></section>`}
const FINE_NAMES={teacher:'賴老師',ah:'何稻禾',an:'許安純',group:'語言文本系學會（9）',lin:'林心愛'};
function memoryRouting(includeNext=false){const lines=VN.memory.lines.slice(0,state.vnStep+1+(includeNext?1:0)),targets=[];let key='an';lines.forEach(([name,text],i)=>{if(name==='許安純')key='an';if(name==='何稻禾')key='ah';if(name==='林心愛')key='lin';if(name==='沈秋'&&/Bailey|稻禾/.test(text))key='ah';targets[i]=key});return {lines,targets,current:key}}
function fineSelected(){if(state.followContact&&Object.values(FINE_NAMES).includes(state.followContact))state.followContact=Object.keys(FINE_NAMES).find(k=>FINE_NAMES[k]===state.followContact);if(state.phase==='vn'&&state.vnKey==='memory')return state.followContact||(memoryReplyReady()?memoryRouting(true).current:memoryRouting().current);if(state.phase==='posterBrief')return state.fineContact||'group';return state.fineContact||['ah','an','teacher'][state.chat]||'teacher'}
function fineKeys(){const late=state.phase==='vn'&&state.vnKey==='memory';const keys=['teacher'];if(state.submitted&&state.progress.teacher>=9||late)keys.push('group','ah');if(state.anUnlocked||late)keys.push('an');if(late&&memoryRouting().targets.includes('lin'))keys.push('lin');return keys}
function fineList(contact){return `<aside class="contacts"><div class="fine-account"><button class="fine-mini-avatar" data-act="avatar:self" aria-label="放大沈秋的頭像"><img src="assets/avatar-qiu-generated.webp" alt="沈秋的楓葉插畫頭貼" width="24" height="24"></button>沈秋<span class="online-dot">●</span></div><div class="finetabs"><span>好友</span><span>聊天</span><span>＋</span></div><div class="fine-contact-scroll">${fineKeys().map(key=>`<div class="contact ${contact===key?'active':''}">${avatar(key==='group'?'group':FINE_NAMES[key])}<button class="contact-open" data-act="finechat:${key}"><span>${named(FINE_NAMES[key])}<small>${key==='group'?'系學會工作聯絡':key==='teacher'?'課務聯絡':'Fine訊息'}</small></span></button></div>`).join('')}</div></aside>`}

function fineThreadReady(key){if(state.phase==='vn'&&state.vnKey==='memory')return true;if(key==='teacher')return true;if(key==='ah')return state.posterDone&&state.posterReceipt;if(key==='an')return state.posterDone&&state.posterReceipt&&state.c1===2&&state.progress.ah>=8&&state.anUnlocked;return false;}
function fineEarly(key){if(!fineThreadReady(key))return {body:'<div class="chatnote">尚未收到訊息。</div>',control:''};const a=thread(key),count=state.progress[key],busy=count<a.length;let body=a.slice(0,count).map(message).join(''),control='';if(busy)body+=a[count]?.photo?'<div class="photo-loading"><span class="loading-wheel"></span><p>正在接收圖片……</p><small>img_353.jpg</small></div>':'<div class="typing">正在傳送訊息……</div>';
if(!busy){if(key==='teacher'){if(!state.ack)control=btn('ack','好的，我看完再把核對結果存到桌面','reply');else if(!state.submitted)control=btn('ppt','開啟文字與閱讀.ppt');else control=btn('friend',state.posterDone&&state.posterReceipt?'查看何稻禾的訊息':'查看系學會群組的新訊息','reply')}else if(key==='ah'){if(state.c1===0)control=btn('reply','我還在353幫老師看教材。你轉給我看看！','reply');else if(state.c1===1)control=btn('reply','我收到了，剩下的我處理就好，你不要害怕','reply');else control=state.anUnlocked?btn('otherchat','查看許安純的新訊息','reply'):'<div class="typing">暫時沒有新的訊息。</div>'}else if(key==='an'){if(state.c2===0)control=btn('reply','也轉給我吧，我先看看是不是同一封','reply');else if(state.c2===1)control=btn('reply','我先各抄一份','reply');else control=btn('startwriting','暫時離開電腦，準備謄寫')}}return {body,control}}
function fineVoice(name,text){return `<div class="message"><div class="sender">${named(name)}</div><div class="bubble fine-voice">${LIN_VOICE_SRC?`<audio controls preload="metadata" aria-label="播放林心愛的Fine語音訊息" src="${LIN_VOICE_SRC}"></audio>`:'<button class="voice-pending" disabled>▶　語音訊息（音檔待提供）</button>'}<details><summary>查看語音文字</summary><p>${esc(text)}</p></details></div></div>`}
function fineUI(){const late=state.phase==='vn'&&state.vnKey==='memory',contact=fineKeys().includes(fineSelected())?fineSelected():'teacher';let body='',control='';if(contact==='group'){body=`<details class="fine-members"><summary>系學會群組　9位成員</summary><p>沈秋、許安純、何稻禾，另6位系學會成員。</p></details>`+POSTER_MESSAGES.slice(0,state.posterBriefCount).map(message).join('');if(state.posterDone){body+=message({name:'沈秋',text:'海報做好了，傳給你們看看！檔案也存在這台電腦上了',self:true});body+=`<div class="message self poster-shared-message"><div class="sender">${named('沈秋')}</div><button class="photo-message" data-act="viewsharedposter"><img src="${state.posterSentImage||posterDataURL()}" width="600" height="800" alt="沈秋傳到系學會群組的招募海報"><span>系學會招募海報・查看圖片</span></button></div>`;body+=state.posterReceipt?message({name:'許安純',text:'收到'}):'<div class="typing">正在傳送訊息……</div>';}if(state.posterBriefCount<POSTER_MESSAGES.length){if(POSTER_MESSAGES[state.posterBriefCount].name==='沈秋')control=btn('postergroupreply',esc(POSTER_MESSAGES[state.posterBriefCount].text)+' ↵','reply');else body+='<div class="typing">正在傳送訊息……</div>';}else if(state.posterBriefCount===POSTER_MESSAGES.length)control=btn('openposter',state.posterDone?'查看／修改海報':'開啟海報編輯器')+(state.posterReceipt&&!late?btn('friend','查看其他訊息','reply'):'');}
else if(contact==='lin'){body='';}else{const early=fineEarly(contact);body=early.body;if(!late)control=early.control;}
if(late){const mem=memoryRouting();body+=mem.lines.map(([name,text],i)=>{if(mem.targets[i]!==contact)return '';if(!name)return '<div class="chatnote">'+esc(text)+'</div>';return name==='林心愛'&&text.startsWith('我當時看見的是')?fineVoice(name,text):message({name,text,self:name==='沈秋'})}).join('');const next=memoryNext(),target=memoryReplyReady()?memoryRouting(true).current:mem.current;if(contact!==target)control=btn('finechat:'+target,'查看目前的對話','reply');else if(!next)control=btn('vnnext','離開電腦，等學姐到353','reply');else if(next[0]==='沈秋')control=btn('vnnext','傳送：'+esc(next[1])+' ↵','reply');else{control='<div class="input-placeholder">等待回覆……</div>';body+='<div class="typing">'+(next[0]?esc(next[0])+'正在輸入訊息……':'等待訊息……')+'</div>'; }}
return `<div class="snshead"><span class="snslogo">Fine</span><small>已登入　沈秋</small></div><div class="snsbody unified-fine">${fineList(contact)}<section class="fine-right"><div class="chatname">${named(FINE_NAMES[contact])}<small>${contact==='group'?'9位成員':'● 線上'}</small></div><div class="chatflow" data-fine-thread="${contact}">${body||'<div class="chatnote">尚未收到訊息。</div>'}</div><div class="fine-input"><div class="input-tools"><span>☺</span><span aria-label="相簿">▧</span></div>${control||'<div class="input-placeholder">等待訊息……</div>'}</div></section></div><div class="appstatus">Fine for PC<span>對話紀錄保存在本機進度</span></div>`}
function setupScenePan(){const pan=document.querySelector('.scene-pan');if(!pan?.addEventListener)return;const key=['worker','workerAfter'].includes(state.phase)?'worker':state.phase;pan.scrollLeft=state.peek?peekFocus(pan,state.peek):scenePanPositions[key]||0;pan.addEventListener('scroll',()=>{if(state.peek){pan.scrollLeft=peekFocus(pan,state.peek);return}scenePanPositions[key]=pan.scrollLeft},{passive:true});pan.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();pan.scrollLeft+=(e.key==='ArrowRight'?1:-1)*Math.max(100,pan.clientWidth*.6)}})}
function desktopFeatureAction(id){if(id.startsWith('avatar:')){const name=id.slice(7);if(AVATARS[name]||name==='group'||name==='self'){fineAvatarPreview=name;modal='avatar';renderModal();}return true;}if(id==='postergroupreply'){if(state.posterBriefCount===2){state.posterBriefCount=3;save();render();}return true;}if(id.startsWith('deck:')){state.deckPage=Math.max(0,Math.min(7,+id.slice(5)||0));save();render();return true}if(id==='startreview'){if(state.teacherRead){state.openCorrected=state.submitted;app(state.submitted?'corrected':'review')}return true}if(id==='fineback'){state.fineContact='group';state.app='sns';phase('posterBrief');return true}if(id.startsWith('finechat:')){const key=id.slice(9);if(!fineKeys().includes(key))return true;if(state.phase==='vn'&&state.vnKey==='memory')state.followContact=key;else{state.fineContact=key;const i=['ah','an','teacher'].indexOf(key);if(i>=0)state.chat=i}save();render();return true}if(id==='showdiagnosis'){roomDetail='diagnosis';sceneTextHidden=false;render();return true}return false}

let fineAvatarPreview='';
function fineAvatarModal(){const n=fineAvatarPreview,label=n==='group'?'語言文本系學會（9）':n==='self'?'沈秋':n;return `<h2>${esc(label)}的頭像</h2>${AVATARS[n]?`<img class="enlarged-avatar" src="assets/${AVATARS[n]}" alt="${esc(label)}的放大頭像">`:`<div class="enlarged-avatar avatar-placeholder">${n==='group'?'系':'沈'}</div>`}`;}
function memoryNext(){return VN.memory.lines[state.vnStep+1];}
function memoryReplyReady(){return memoryNext()?.[0]==='沈秋';}
function advanceMemoryLine(){if(state.phase!=='vn'||state.vnKey!=='memory'||!memoryNext())return;state.vnStep++;save();render();}
function scheduleMemory(){const next=memoryNext();if(!next||next[0]==='沈秋')return;const step=state.vnStep;once('fine-memory:'+step,MESSAGE_DELAY,()=>{if(state.phase!=='vn'||state.vnKey!=='memory'||state.vnStep!==step)return;advanceMemoryLine();});}
